mapper.select:

WHERE f.del_flag = '0'

    AND f.feedback_no = #{query.feedbackNo}


    AND f.feedback_type = #{query.feedbackType}


    AND f.status = #{query.status}


    AND f.input_id = #{query.inputId}


    AND f.supplier_id = #{query.supplierId}


    AND f.handler_id = #{query.handlerId}


    AND f.title LIKE CONCAT('%', #{query.titleKeyword}, '%')


    AND f.content LIKE CONCAT('%', #{query.contentKeyword}, '%')


    AND f.contact_name LIKE CONCAT('%', #{query.contactName}, '%')


    AND f.contact_phone LIKE CONCAT('%', #{query.contactPhone}, '%')


    AND DATE(f.create_time) >= #{query.startTime}


    AND DATE(f.create_time) <= #{query.endTime}

ORDER BY f.create_time DESC
